// Launch Params: the launch row is the contract (Rootflow rule): Client (resolves the base), Table
// (must be People), View (by name, required), Tag (log only). Nothing else is read. A badly filled
// row throws here, before any table is read or any verification is paid.
const rec=$('Fetch Launch Record').first().json||{};
const f=rec.fields||{};
const cf=(($('Resolve Base').first().json||{}).fields)||{};
const base=String(cf['Clayroots Base ID']||'').trim();
const arr=(v)=>Array.isArray(v)?v:(v==null||v===''?[]:[v]);
const clientRecId=(arr(f['Client']).map(x=>(x&&typeof x==='object')?x.id:x)[0])||'';
const table=String(f['Table']||'').trim();
const view=String(f['View']||'').trim();
const where='Launch record '+(rec.id||'?');
if(!clientRecId) throw new Error(where+' has no Client link. Nothing was verified.');
if(!/^app[A-Za-z0-9]{14}$/.test(base)) throw new Error('Client on '+where.toLowerCase()+' has no valid Clayroots Base ID. Nothing was verified.');
// Table is implied (People); ruled 2026-09-09: the launch row is Client, View, Tag.
if(table&&table.toLowerCase()!=='people') throw new Error(where+' names Table "'+table+'". Enrich Emails runs on People (company inboxes are Verify Emails). Nothing was verified.');
if(!view) throw new Error(where+' has no View. A People view is required by name. Nothing was verified.');
return [{ json:{ base, clientRecId, table:'People', view, tag:String(f['Tag']||'').trim(), trigger:'form', _launchRecordId:rec.id||'', startedAt:new Date().toISOString() } }];

// Event Params: the record door. Enrich Contacts POSTs {baseId, clientRecordId, table, view} once
// after its last batch (the best use of this Rootflow: the People view "Not Waterfalled"); any
// caller may POST the same shape for any People view. The door answers 200 on receipt and the run
// carries on alone, so a caller never waits on a verification.
const b=($input.first().json||{}).body||{};
const base=String(b.baseId||b.base||'').trim();
const table=String(b.table||'People').trim();
const view=String(b.view||'').trim();
if(!/^app[A-Za-z0-9]{14}$/.test(base)) throw new Error('Enrich Emails record door: no valid baseId in the body. Nothing was verified.');
if(table.toLowerCase()!=='people') throw new Error('Enrich Emails record door: Table "'+table+'" is not People. Nothing was verified.');
if(!view) throw new Error('Enrich Emails record door: no view in the body. Nothing was verified.');
return [{ json:{ base, clientRecId:String(b.clientRecordId||b.clientRecId||'').trim(), table:'People', view, tag:'', trigger:'event', _launchRecordId:'', startedAt:new Date().toISOString() } }];

// Params: one shape for both entries. Whichever entry ran wrote its item; this re-emits it so every
// node after reads $('Params') and never cares which door opened the run.
let p=null;
try{ p=$('Launch Params').first().json; }catch(e){}
if(!p||!p.base){ try{ p=$('Event Params').first().json; }catch(e){} }
if(!p||!p.base) throw new Error('Enrich Emails: no entry produced launch parameters.');
return [{ json:p }];

// Resolve Table: People by name in the base meta just read, the view by name or id (both required,
// no defaults). Field names and types travel for the requirements check. Nothing here creates.
const p=$('Params').first().json;
const r=$input.first().json||{}; const body=(r.body!==undefined)?r.body:r;
const tables=(body&&Array.isArray(body.tables))?body.tables:null;
if(!tables) throw new Error('Could not read the table list for base '+p.base+': '+JSON.stringify(body).slice(0,200)+'. Nothing was verified.');
const t=tables.find(x=>String(x.name||'').trim().toLowerCase()==='people');
if(!t) throw new Error('Base '+p.base+' has no People table. Nothing was verified.');
const v=(t.views||[]).find(x=>x.id===p.view||String(x.name||'').trim()===p.view);
if(!v) throw new Error('People ('+t.id+') in base '+p.base+' has no view "'+p.view+'". Nothing was verified.');
const types={}; for(const f of (t.fields||[])) types[f.name]=f.type;
return [{ json:{ tableId:t.id, tableName:t.name, viewId:v.id, viewName:v.name, fieldNames:(t.fields||[]).map(f=>f.name), fieldTypes:types } }];

// Check Columns: the Rootflow's requirements and its own fields. Requirements (must exist, written
// by others): first_name, last_name, Domain, Email, LinkedIn URL, Status. Refused by name when one is
// missing. Own fields (created here on first use, the Rootflow rule; never renamed or retyped):
//   Final Email          singleLineText   the address that goes out
//   Email Provider       singleSelect     where Final Email came from: database, pattern, Blitz,
//                                         LeadMagic, ... (typecast mints a new provider's name)
//   Email Verified By    singleSelect     MillionVerifier or BounceBan
//   Email Verified At    dateTime
//   Email Candidates     singleLineText   "email|origin, ..." while a catch-all row waits for
//                                         Verify Catch-alls; cleared when it settles
// Status is a requirement (the register's select: done, verifying, no_email_found, error).
const p=$('Params').first().json;
const t=$('Resolve Table').first().json;
const have=new Set(t.fieldNames||[]);
const REQUIRED=['first_name','last_name','Domain','Email','LinkedIn URL','Status'];
const missing=REQUIRED.filter(n=>!have.has(n));
if(missing.length) throw new Error('People ('+t.tableId+') in base '+p.base+' is missing '+missing.join(', ')+'. Enrich Emails needs them and creates only its own fields. Nothing was verified.');
const OWN=[
  { name:'Final Email', type:'singleLineText' },
  { name:'Email Provider', type:'singleSelect', options:{ choices:[{name:'database',color:'blueLight2'},{name:'pattern',color:'cyanLight2'},{name:'Blitz',color:'tealLight2'},{name:'LeadMagic',color:'purpleLight2'}] } },
  { name:'Email Verified By', type:'singleSelect', options:{ choices:[{name:'MillionVerifier',color:'greenLight2'},{name:'BounceBan',color:'yellowLight2'}] } },
  { name:'Email Verified At', type:'dateTime', options:{ dateFormat:{name:'iso'}, timeFormat:{name:'24hour'}, timeZone:'utc' } },
  { name:'Email Candidates', type:'singleLineText' }
];
const toCreate=OWN.filter(f=>!have.has(f.name));
const url='https://api.airtable.com/v0/meta/bases/'+p.base+'/tables/'+t.tableId+'/fields';
return [{ json:{ base:p.base, tableId:t.tableId, toCreate:toCreate.map(f=>f.name), creates:toCreate.map(f=>({ url:url, body:f })), startedAt:p.startedAt } }];

// Plan Columns: one meta-API call per own field the table lacks. Runs only when there is something
// to create; the IF before it routes an empty plan straight to the row read.
const c=$('Check Columns').first().json;
return (c.creates||[]).map(x=>({ json:x }));

// Verify Columns: the base meta read again after the creates. Every own field must now show;
// anything still missing stops the run by name before a row is read.
const c=$('Check Columns').first().json;
const r=$input.first().json||{}; const body=(r.body!==undefined)?r.body:r;
const tables=(body&&Array.isArray(body.tables))?body.tables:null;
if(!tables) throw new Error('Could not re-read the table list for base '+c.base+' after creating columns: '+JSON.stringify(body).slice(0,200)+'.');
const names=new Set((((tables.find(t=>t.id===c.tableId))||{}).fields||[]).map(f=>f.name));
const still=(c.toCreate||[]).filter(n=>!names.has(n));
if(still.length) throw new Error('Enrich Emails created columns the base does not show: '+still.join(', ')+'. Nothing was verified.');
return [{ json:{ created:c.toCreate.slice() } }];

// Pack Rows: every row of the view, each carrying the run context the batch sub-execution needs
// (Params and Resolve Table do not exist inside a sub-execution). One row = one person to resolve.
const p=$('Params').first().json;
const t=$('Resolve Table').first().json;
const rows=$input.all().map(i=>i.json).filter(j=>j&&j.id);
const ctx={ _baseId:p.base, _tableId:t.tableId, _tableName:t.tableName, _view:t.viewName, _execId:String($execution.id), _startedAt:p.startedAt, _clientId:p.clientRecId||'', _trigger:p.trigger||'form', _total:rows.length, _tag:p.tag||'' };
return rows.map(j=>({ json:Object.assign({}, j, ctx) }));

// Verify Handoff: after the last batch, one item for Verify Catch-alls on the WHOLE People table
// (no view): the rows this run just marked verifying have left the view it worked (Not Waterfalled
// is Status empty), and Verify Catch-alls filters Status = verifying itself. Fired, not awaited: it
// writes its own Hub row keyed on this execution.
const p=$('Params').first().json;
return [{ json:{ base:p.base, clientRecId:p.clientRecId||'', table:'People', view:'', parentExecId:String($execution.id) } }];

// Build Log: the run's final row. The batches accumulated their counters in this row's Tally (each
// sub-execution reads the row, adds its slice, writes it back with Status Running); this pass reads
// the accumulated Tally once more and writes the verdict. A run with no rows writes its trace too.
const p=$('Params').first().json;
let t={}; try{ t=$('Resolve Table').first().json||{}; }catch(e){}
let total=0; try{ total=$('Fetch Rows').all().filter(i=>i.json&&i.json.id).length; }catch(e){}
const BLANK={ rows:0, done:0, verifying:0, noEmail:0, errored:0, byProvider:{}, mvCalls:0, blitzCalls:0, blitzFound:0, lmCalls:0, lmFound:0, guesses:0, catchAllDomains:0, written:0, writeErrors:0, writeWhy:[], batches:0 };
let a=Object.assign({},BLANK);
try{ const prior=$('Read Run Row').first().json; const raw=prior&&prior.fields?prior.fields.Tally:null; if(raw){ const parsed=JSON.parse(String(raw)); if(parsed&&String(parsed.execId)===String($execution.id)) a=Object.assign({},BLANK,parsed); } }catch(e){}
let handoff='not fired'; try{ const h=$('Fire Verify Catch-alls').first().json||{}; handoff=(h.error)?('failed: '+String((h.error&&h.error.message)||h.error).slice(0,120)):'fired once after the last batch (it filters Status = verifying itself and writes its own row)'; }catch(e){ handoff=total?'not fired':'not needed, no rows'; }
const n=(v)=>Number(v)||0;
let dur=0; try{ dur=Math.max(0,Math.round(($now.toMillis()-new Date(p.startedAt).getTime())/1000)); }catch(e){}
const prov=Object.entries(a.byProvider||{}).map(([k,v])=>k+' '+v).join(', ')||'none';
const lines=[
  '**'+n(a.rows)+' people worked, '+n(a.done)+' resolved, '+n(a.verifying)+' waiting on BounceBan (catch-all domains), '+n(a.noEmail)+' no email found, '+n(a.errored)+' errored**',
  '',
  '**Scope:** one client, People view "'+(t.viewName||p.view)+'"'+(p.tag?', Tag "'+p.tag+'"':'')+', '+total+' rows read, '+n(a.batches)+' batches of 100',
  '**Rule:** candidates in Email verified first (MillionVerifier); Blitz email by LinkedIn URL; one guess from the domain pattern our base already proves; six common patterns; LeadMagic last. Catch-all is decided per domain: rows there go to Verify Catch-alls with their candidates.',
  '',
  '**Results**',
  '- **Resolved by provider:** '+prov,
  '- **MillionVerifier calls:** '+n(a.mvCalls)+'; **guesses tried:** '+n(a.guesses)+'; **Blitz:** '+n(a.blitzCalls)+' asked, '+n(a.blitzFound)+' found; **LeadMagic:** '+n(a.lmCalls)+' asked, '+n(a.lmFound)+' found',
  '- **Catch-all domains met:** '+n(a.catchAllDomains),
  '- **Rows written (confirmed by Airtable):** '+n(a.written)+(n(a.writeErrors)?', '+n(a.writeErrors)+' refused':''),
  '- **Verify Catch-alls:** '+handoff
];
if(!total) lines.push('', '**Skipped (view "'+p.view+'" had no rows)**');
if((a.writeWhy||[]).length){ lines.push('', '**Write failures**'); for(const w of a.writeWhy.slice(0,10)) lines.push('- '+w); }
const failed=n(a.errored)+n(a.writeErrors);
const log={
  'Execution ID': String($execution.id),
  'Automation': 'Enrich Emails',
  'Status': failed?'Succeeded with errors':'Succeeded',
  'Trigger': p.trigger||'form',
  'Errors': failed,
  'Run at': p.startedAt,
  'Target': (t.tableName||'People')+' ('+(t.tableId||'')+')',
  'View': t.viewName||p.view,
  'Records In': total,
  'Records Out': n(a.written),
  'Duration s': dur,
  'Description': lines.join('\n'),
  'Tally': JSON.stringify(Object.assign({}, a, { execId:String($execution.id) })),
  'Execution Link': 'https://n8n.flowroots.com/workflow/'+$workflow.id+'/executions/'+$execution.id
};
if(p.clientRecId) log['Client']=[p.clientRecId];
return [{ json:log }];

// Known Filters: the domains of this batch, one OR formula per 100, for the read of what the base
// already PROVES at those domains: People rows with Status = done carry a verified Final Email, and
// from them the domain's address pattern is inferred (one guess instead of six) and a domain that
// BounceBan verified is known catch-all before anyone is asked. Domain on People is a lookup.
const rows=$('Read Records').all().map(i=>i.json||{}).filter(j=>j.id);
const norm=(v)=>String(Array.isArray(v)?(v[0]||''):(v||'')).trim().toLowerCase();
const d=Array.from(new Set(rows.map(r=>norm((r.fields||{}).Domain)).filter(Boolean)));
const esc=(s)=>String(s).replace(/\\/g,'\\\\').replace(/'/g,"\\'");
const out=[];
for(let i=0;i<d.length;i+=100){ const chunk=d.slice(i,i+100); out.push({ json:{ formula:"AND({Status}='done',"+(chunk.length===1?("{Domain}='"+esc(chunk[0])+"'"):('OR('+chunk.map(x=>"{Domain}='"+esc(x)+"'").join(',')+')'))+")" } }); }
if(!out.length) out.push({ json:{ formula:"{Domain}=''" } });
return out;

// Prep: the batch's state, one item, carried from stage to stage by name. Per row: the cleaned
// names, the domain, the LinkedIn URL, and the candidate list built from the Email cell (every
// address the contact providers delivered, in the order they were merged; a foreign-domain address
// is kept last). Per domain: the address pattern the base already proves (from Status = done rows
// at that domain whose Final Email matches one of the known shapes for that person: the majority
// shape, at least one proof) and whether the domain is known catch-all (a done row there was
// verified by BounceBan). Shapes: first.last, first, flast, firstlast, first_last, f.last.
const rows=$('Read Records').all().map(i=>i.json||{}).filter(j=>j.id);
let known=[]; try{ known=$('Read Known').all().map(i=>i.json||{}).filter(j=>j.id); }catch(e){}
const norm=(v)=>String(Array.isArray(v)?(v[0]||''):(v||'')).trim().toLowerCase();
const clean=(s)=>String(s||'').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g,'').replace(/[^a-z]/g,'');
const SHAPES=['first.last','first','flast','firstlast','first_last','f.last'];
const shape=(sh,f,l)=>{ if(!f) return ''; if(sh==='first') return f; if(!l) return ''; if(sh==='first.last') return f+'.'+l; if(sh==='flast') return f.charAt(0)+l; if(sh==='firstlast') return f+l; if(sh==='first_last') return f+'_'+l; if(sh==='f.last') return f.charAt(0)+'.'+l; return ''; };
const splitEmails=(s)=>Array.from(new Set(String(s||'').split(/[,;\s]+/).map(e=>e.trim().toLowerCase()).filter(e=>/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(e))));
const domainOf=(e)=>e.slice(e.lastIndexOf('@')+1);
// What the base proves per domain.
const proof={};
for(const k of known){ const f=k.fields||{}; const d=norm(f.Domain); const fe=String(f['Final Email']||'').trim().toLowerCase(); if(!d||!fe) continue; const p=proof[d]||(proof[d]={ shapes:{}, catchAll:false }); if(String(f['Email Verified By']||'')==='BounceBan') p.catchAll=true; const first=clean(f.first_name), last=clean(f.last_name); const local=fe.slice(0,fe.lastIndexOf('@')); for(const sh of SHAPES){ if(shape(sh,first,last)===local){ p.shapes[sh]=(p.shapes[sh]||0)+1; break; } } }
const patterns={}, domainCatchAll={};
for(const d of Object.keys(proof)){ const p=proof[d]; if(p.catchAll) domainCatchAll[d]=true; let best='',n=0; for(const sh of Object.keys(p.shapes)){ if(p.shapes[sh]>n){ n=p.shapes[sh]; best=sh; } } if(best) patterns[d]=best; }
const state={ order:[], rows:{}, patterns, domainCatchAll, stats:{ rows:rows.length, candidatesIn:0, knownRows:known.length, patternsKnown:Object.keys(patterns).length, mvCalls:0, blitzCalls:0, blitzFound:0, lmCalls:0, lmFound:0, guesses:0, catchAllDomains:0 } };
for(const r of rows){
  const f=r.fields||{};
  const domain=norm(f.Domain);
  const first=clean(f.first_name), last=clean(f.last_name);
  const emails=splitEmails(f.Email);
  const own=emails.filter(e=>domain&&(domainOf(e)===domain||domainOf(e).endsWith('.'+domain)));
  const foreign=emails.filter(e=>own.indexOf(e)<0);
  const candidates=own.concat(foreign).map(e=>({ email:e, origin:'database', mv:'' }));
  state.stats.candidatesIn+=candidates.length;
  state.order.push(r.id);
  state.rows[r.id]={ id:r.id, first, last, firstRaw:String(f.first_name||'').trim(), lastRaw:String(f.last_name||'').trim(), domain, linkedin:String(f['LinkedIn URL']||'').trim(), candidates, resolved:null, catchAll:!!domainCatchAll[domain], guessed:false, blitzAsked:false, lmAsked:false, error:'' };
}
state.stats.catchAllDomains=Object.keys(domainCatchAll).length;
return [{ json:state }];

// MV Cand Requests: one MillionVerifier call per untried candidate on every row that is not resolved and
// not on a catch-all domain (a catch-all domain gets no MillionVerifier: its verdict is the same for
// every address there). Candidates on catch-all rows are marked tried without a call. Emits
// {_none:true} when there is nothing to verify, so the IF after it skips the HTTP node.
const state=$('Prep').first().json;
const out=[];
for(const id of state.order){
  const r=state.rows[id];
  if(r.resolved) continue;
  for(const c of r.candidates){
    if(c.mv) continue;
    if(r.catchAll){ c.mv='catch_all'; continue; }
    out.push({ json:{ rowId:id, email:c.email, origin:c.origin } });
  }
}
if(!out.length) return [{ json:{ _none:true } }];
return out;

// MV Cand Collect: the MillionVerifier answers of MV Candidates (aligned by index to MV Cand Requests) folded into the
// state from Prep. Per candidate: ok, catch_all, invalid, disposable, unknown, error. The first
// ok in candidate order resolves the row (Email Verified By MillionVerifier). One catch_all marks
// the domain for the whole batch: every other row there skips MillionVerifier from now on. A
// MillionVerifier out-of-credits answer stops the run here, loudly: nothing can be verified without
// it (the same law as the old waterfall). Never re-asks a candidate.
const state=$('Prep').first().json;
let reqs=[]; try{ reqs=$('MV Cand Requests').all().map(i=>i.json||{}).filter(j=>!j._none); }catch(e){}
let answers=[]; try{ answers=$('MV Candidates').all(); }catch(e){}
const OK=['ok','catch_all','invalid','disposable','unknown'];
answers.forEach((it,i)=>{
  const q=reqs[i]; if(!q) return;
  const j=it.json||{};
  state.stats.mvCalls++;
  const r=state.rows[q.rowId]; if(!r) return;
  const c=r.candidates.find(x=>x.email===q.email&&!x.mv); if(!c) return;
  const dry=/insufficient credit|no credit|out of credit/i.test(String(j.error||''))||(Number.isFinite(Number(j.credits))&&Number(j.credits)<0);
  if(dry) throw new Error('MillionVerifier is out of credits (balance '+String(j.credits)+'). Nothing can be verified without it, so the run is stopping here. Top up and relaunch.');
  const res=OK.indexOf(j.result)>-1?j.result:'error';
  c.mv=res;
  if(res==='catch_all'){ r.catchAll=true; if(r.domain&&!state.domainCatchAll[r.domain]){ state.domainCatchAll[r.domain]=true; state.stats.catchAllDomains++; } for(const o of r.candidates){ if(!o.mv) o.mv='catch_all'; } }
});
for(const id of state.order){
  const r=state.rows[id]; if(r.resolved||r.catchAll) continue;
  const hit=r.candidates.find(x=>x.mv==='ok');
  if(hit) r.resolved={ email:hit.email, origin:hit.origin, by:'MillionVerifier' };
}
return [{ json:state }];

// Blitz Requests: one POST /v2/enrichment/email per unresolved row that carries a LinkedIn URL
// (the URL passed the name fence when the person landed). Blitz's email finder keys on the profile
// URL only; it is flat-rate, so it comes before any guess. Asked on catch-all rows too: there its
// answer is a candidate for BounceBan. {_none:true} when nothing to ask.
const state=$('MV Cand Collect').first().json;
const out=[];
for(const id of state.order){ const r=state.rows[id]; if(r.resolved||!r.linkedin||r.blitzAsked) continue; r.blitzAsked=true; out.push({ json:{ rowId:id, body:{ person_linkedin_url:r.linkedin } } }); }
if(!out.length) return [{ json:{ _none:true } }];
return out;

// Blitz Collect: the finder's answers (aligned to Blitz Requests) become candidates with origin
// Blitz: the top email, plus every all_emails entry for the current job (job_order_in_profile 1)
// at the row's domain. A missing credential or a dead API is counted and the stage is skipped for
// this batch, never an error that stops the run. The candidates are verified by the MV stage after.
const state=$('MV Cand Collect').first().json;
let reqs=[]; try{ reqs=$('Blitz Requests').all().map(i=>i.json||{}).filter(j=>!j._none); }catch(e){}
let answers=[]; try{ answers=$('Blitz Email').all(); }catch(e){}
const errMsg=(e)=>{ if(!e) return 'call failed'; if(typeof e==='string') return e; return String((e.message||'')+' '+(e.description||'')).trim()||'call failed'; };
state.stats.blitzSkipped=state.stats.blitzSkipped||'';
answers.forEach((it,i)=>{
  const q=reqs[i]; if(!q) return;
  const j=it.json||{};
  state.stats.blitzCalls++;
  if(j.error&&j.body===undefined&&j.found===undefined){ const m=errMsg(j.error); if(/credential/i.test(m)) state.stats.blitzSkipped='no credential on the Blitz node'; else state.stats.blitzSkipped=m.slice(0,120); return; }
  const b=(j.body!==undefined)?j.body:j;
  if(!b||typeof b!=='object'||!b.found) return;
  const r=state.rows[q.rowId]; if(!r) return;
  const list=[]; if(b.email) list.push(String(b.email).toLowerCase());
  for(const e of (Array.isArray(b.all_emails)?b.all_emails:[])){ if(e&&e.email&&Number(e.job_order_in_profile)===1) list.push(String(e.email).toLowerCase()); }
  let added=0;
  for(const e of list){ if(!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(e)) continue; if(r.candidates.some(c=>c.email===e)) continue; r.candidates.push({ email:e, origin:'Blitz', mv:'' }); added++; }
  if(added) state.stats.blitzFound++;
});
return [{ json:state }];

// MV Blitz Requests: one MillionVerifier call per untried candidate on every row that is not resolved and
// not on a catch-all domain (a catch-all domain gets no MillionVerifier: its verdict is the same for
// every address there). Candidates on catch-all rows are marked tried without a call. Emits
// {_none:true} when there is nothing to verify, so the IF after it skips the HTTP node.
const state=$('Blitz Collect').first().json;
const out=[];
for(const id of state.order){
  const r=state.rows[id];
  if(r.resolved) continue;
  for(const c of r.candidates){
    if(c.mv) continue;
    if(r.catchAll){ c.mv='catch_all'; continue; }
    out.push({ json:{ rowId:id, email:c.email, origin:c.origin } });
  }
}
if(!out.length) return [{ json:{ _none:true } }];
return out;

// MV Blitz Collect: the MillionVerifier answers of MV Blitz (aligned by index to MV Blitz Requests) folded into the
// state from Blitz Collect. Per candidate: ok, catch_all, invalid, disposable, unknown, error. The first
// ok in candidate order resolves the row (Email Verified By MillionVerifier). One catch_all marks
// the domain for the whole batch: every other row there skips MillionVerifier from now on. A
// MillionVerifier out-of-credits answer stops the run here, loudly: nothing can be verified without
// it (the same law as the old waterfall). Never re-asks a candidate.
const state=$('Blitz Collect').first().json;
let reqs=[]; try{ reqs=$('MV Blitz Requests').all().map(i=>i.json||{}).filter(j=>!j._none); }catch(e){}
let answers=[]; try{ answers=$('MV Blitz').all(); }catch(e){}
const OK=['ok','catch_all','invalid','disposable','unknown'];
answers.forEach((it,i)=>{
  const q=reqs[i]; if(!q) return;
  const j=it.json||{};
  state.stats.mvCalls++;
  const r=state.rows[q.rowId]; if(!r) return;
  const c=r.candidates.find(x=>x.email===q.email&&!x.mv); if(!c) return;
  const dry=/insufficient credit|no credit|out of credit/i.test(String(j.error||''))||(Number.isFinite(Number(j.credits))&&Number(j.credits)<0);
  if(dry) throw new Error('MillionVerifier is out of credits (balance '+String(j.credits)+'). Nothing can be verified without it, so the run is stopping here. Top up and relaunch.');
  const res=OK.indexOf(j.result)>-1?j.result:'error';
  c.mv=res;
  if(res==='catch_all'){ r.catchAll=true; if(r.domain&&!state.domainCatchAll[r.domain]){ state.domainCatchAll[r.domain]=true; state.stats.catchAllDomains++; } for(const o of r.candidates){ if(!o.mv) o.mv='catch_all'; } }
});
for(const id of state.order){
  const r=state.rows[id]; if(r.resolved||r.catchAll) continue;
  const hit=r.candidates.find(x=>x.mv==='ok');
  if(hit) r.resolved={ email:hit.email, origin:hit.origin, by:'MillionVerifier' };
}
return [{ json:state }];

// Add Guesses: for every unresolved row on a non-catch-all domain, the guesses become candidates
// with origin pattern, in this order: one guess from the shape the base already proves at that
// domain (gated: only from Status = done rows there, majority shape), then the six most common
// corporate shapes: first.last, first, flast, firstlast, first_last, f.last. A shape whose address
// is already a candidate (delivered by a provider, or already tried) is not repeated. A row without
// a first name gets no guess; shapes that need a last name are skipped when there is none.
const state=$('MV Blitz Collect').first().json;
const SHAPES=['first.last','first','flast','firstlast','first_last','f.last'];
const shape=(sh,f,l)=>{ if(!f) return ''; if(sh==='first') return f; if(!l) return ''; if(sh==='first.last') return f+'.'+l; if(sh==='flast') return f.charAt(0)+l; if(sh==='firstlast') return f+l; if(sh==='first_last') return f+'_'+l; if(sh==='f.last') return f.charAt(0)+'.'+l; return ''; };
for(const id of state.order){
  const r=state.rows[id];
  if(r.resolved||r.catchAll||r.guessed||!r.domain||!r.first) continue;
  r.guessed=true;
  const order=[]; const known=state.patterns[r.domain]; if(known) order.push(known); for(const sh of SHAPES){ if(order.indexOf(sh)<0) order.push(sh); }
  const have=new Set(r.candidates.map(c=>c.email));
  for(const sh of order){ const local=shape(sh,r.first,r.last); if(!local) continue; const e=local+'@'+r.domain; if(have.has(e)) continue; have.add(e); r.candidates.push({ email:e, origin:'pattern', mv:'', shape:sh }); state.stats.guesses++; }
}
return [{ json:state }];

// MV Guess Requests: one MillionVerifier call per untried candidate on every row that is not resolved and
// not on a catch-all domain (a catch-all domain gets no MillionVerifier: its verdict is the same for
// every address there). Candidates on catch-all rows are marked tried without a call. Emits
// {_none:true} when there is nothing to verify, so the IF after it skips the HTTP node.
const state=$('Add Guesses').first().json;
const out=[];
for(const id of state.order){
  const r=state.rows[id];
  if(r.resolved) continue;
  for(const c of r.candidates){
    if(c.mv) continue;
    if(r.catchAll){ c.mv='catch_all'; continue; }
    out.push({ json:{ rowId:id, email:c.email, origin:c.origin } });
  }
}
if(!out.length) return [{ json:{ _none:true } }];
return out;

// MV Guess Collect: the MillionVerifier answers of MV Guesses (aligned by index to MV Guess Requests) folded into the
// state from Add Guesses. Per candidate: ok, catch_all, invalid, disposable, unknown, error. The first
// ok in candidate order resolves the row (Email Verified By MillionVerifier). One catch_all marks
// the domain for the whole batch: every other row there skips MillionVerifier from now on. A
// MillionVerifier out-of-credits answer stops the run here, loudly: nothing can be verified without
// it (the same law as the old waterfall). Never re-asks a candidate.
const state=$('Add Guesses').first().json;
let reqs=[]; try{ reqs=$('MV Guess Requests').all().map(i=>i.json||{}).filter(j=>!j._none); }catch(e){}
let answers=[]; try{ answers=$('MV Guesses').all(); }catch(e){}
const OK=['ok','catch_all','invalid','disposable','unknown'];
answers.forEach((it,i)=>{
  const q=reqs[i]; if(!q) return;
  const j=it.json||{};
  state.stats.mvCalls++;
  const r=state.rows[q.rowId]; if(!r) return;
  const c=r.candidates.find(x=>x.email===q.email&&!x.mv); if(!c) return;
  const dry=/insufficient credit|no credit|out of credit/i.test(String(j.error||''))||(Number.isFinite(Number(j.credits))&&Number(j.credits)<0);
  if(dry) throw new Error('MillionVerifier is out of credits (balance '+String(j.credits)+'). Nothing can be verified without it, so the run is stopping here. Top up and relaunch.');
  const res=OK.indexOf(j.result)>-1?j.result:'error';
  c.mv=res;
  if(res==='catch_all'){ r.catchAll=true; if(r.domain&&!state.domainCatchAll[r.domain]){ state.domainCatchAll[r.domain]=true; state.stats.catchAllDomains++; } for(const o of r.candidates){ if(!o.mv) o.mv='catch_all'; } }
});
for(const id of state.order){
  const r=state.rows[id]; if(r.resolved||r.catchAll) continue;
  const hit=r.candidates.find(x=>x.mv==='ok');
  if(hit) r.resolved={ email:hit.email, origin:hit.origin, by:'MillionVerifier' };
}
return [{ json:state }];

// LM Requests: LeadMagic, the one paid finder, only for rows where everything else failed: not
// resolved, not on a catch-all domain, first and last name and domain present. Rare by
// construction, and only on the relevant people the view holds. {_none:true} when nothing to ask.
const state=$('MV Guess Collect').first().json;
const out=[];
for(const id of state.order){ const r=state.rows[id]; if(r.resolved||r.catchAll||r.lmAsked||!r.domain||!r.firstRaw||!r.lastRaw) continue; r.lmAsked=true; out.push({ json:{ rowId:id, body:{ first_name:r.firstRaw, last_name:r.lastRaw, domain:r.domain } } }); }
if(!out.length) return [{ json:{ _none:true } }];
return out;

// LM Collect: LeadMagic's answers (aligned to LM Requests) become candidates with origin LeadMagic.
// Its negatives ("couldn't find", "unable to verify") and an out-of-credits answer are counted,
// never errors. The candidate is verified by the MV stage after.
const state=$('MV Guess Collect').first().json;
let reqs=[]; try{ reqs=$('LM Requests').all().map(i=>i.json||{}).filter(j=>!j._none); }catch(e){}
let answers=[]; try{ answers=$('LeadMagic Find').all(); }catch(e){}
state.stats.lmSkipped=state.stats.lmSkipped||'';
answers.forEach((it,i)=>{
  const q=reqs[i]; if(!q) return;
  const j=it.json||{};
  state.stats.lmCalls++;
  if(j.error&&typeof j.error==='object'&&j.email===undefined){ const m=String(j.error.message||j.error.description||''); if(/credential/i.test(m)) state.stats.lmSkipped='no credential on the LeadMagic node'; return; }
  const txt=JSON.stringify(j).toLowerCase();
  if(/insufficient_credits|insufficient credit|out of credits/.test(txt)){ state.stats.lmSkipped='out of credits'; return; }
  const e=String(j.email||'').trim().toLowerCase();
  if(!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(e)) return;
  const r=state.rows[q.rowId]; if(!r) return;
  if(r.candidates.some(c=>c.email===e)) return;
  r.candidates.push({ email:e, origin:'LeadMagic', mv:'' }); state.stats.lmFound++;
});
return [{ json:state }];

// MV LM Requests: one MillionVerifier call per untried candidate on every row that is not resolved and
