// Verdict: one write per row from the final state. done: Final Email, Email Provider (the
// candidate's origin), Email Verified By MillionVerifier, Email Verified At, Status done, Email
// Candidates cleared. A catch-all row: Status verifying, Email Candidates = up to three candidates
// in priority order as "email|origin" (database, Blitz, LeadMagic, then the pattern guesses) for
// Verify Catch-alls, which picks the first BounceBan says is deliverable. Nothing found on a normal
// domain: no_email_found. Nothing could be asked (no name, no domain, every verifier answer an
// error): error, retryable. Email is rewritten as the full candidate list so a later pass starts
// from everything that was ever found.
const state=$('MV LM Collect').first().json;
const now=new Date().toISOString();
const PRI={ database:0, Blitz:1, LeadMagic:2, pattern:3 };
const out=[];
const st={ done:0, verifying:0, noEmail:0, errored:0, byProvider:{} };
for(const id of state.order){
  const r=state.rows[id];
  const all=Array.from(new Set(r.candidates.map(c=>c.email)));
  const row={ id:id, 'Email':all.join(', ') };
  if(r.resolved){
    row['Final Email']=r.resolved.email; row['Email Provider']=r.resolved.origin; row['Email Verified By']=r.resolved.by||'MillionVerifier'; row['Email Verified At']=now; row['Status']='done'; row['Email Candidates']='';
    st.done++; st.byProvider[r.resolved.origin]=(st.byProvider[r.resolved.origin]||0)+1;
  } else if(r.catchAll){
    const cands=r.candidates.slice().sort((a,b)=>(PRI[a.origin]-PRI[b.origin]));
    const guesses=cands.filter(c=>c.origin==='pattern');
    // on a catch-all domain the guesses were never made (no MillionVerifier there); add the two most
    // common shapes so BounceBan has something to rank when no provider delivered an address
    if(!guesses.length&&r.first&&r.domain){ const g=[ (r.last?(r.first+'.'+r.last):''), r.first ].filter(Boolean).map(l=>({ email:l+'@'+r.domain, origin:'pattern' })); for(const c of g){ if(!cands.some(x=>x.email===c.email)) cands.push(c); } }
    const pick=cands.slice(0,3);
    row['Status']='verifying'; row['Email Candidates']=pick.map(c=>c.email+'|'+c.origin).join(', '); row['Email']=Array.from(new Set(all.concat(pick.map(c=>c.email)))).join(', ');
    st.verifying++;
  } else {
    const tried=r.candidates.filter(c=>c.mv&&c.mv!=='error'&&c.mv!=='unknown').length;
    const answered=r.candidates.some(c=>c.mv&&c.mv!=='error');
    if(r.candidates.length&&!answered){ row['Status']='error'; st.errored++; }
    else { row['Status']='no_email_found'; row['Email Candidates']=''; st.noEmail++; }
    if(!tried&&!r.candidates.length){ row['Status']=r.first&&r.domain?'no_email_found':'error'; }
  }
  out.push({ json:row });
}
if(out.length) out[0].json._stats=Object.assign({}, st, state.stats);
if(!out.length) return [{ json:{ _empty:true, _stats:Object.assign({}, st, state.stats) } }];
return out;

// Chunk Rows: the verdict rows in tens, one item per Airtable request, PATCHed as {records:[{id,
// fields}], typecast:true} 200 ms apart (typecast lets a new provider's name mint its choice on
// Email Provider). Ids and size ride on the item for the count-back; carriers are stripped.
const rows=$input.all().map(i=>i.json).filter(j=>j&&j.id&&!j._empty);
const out=[];
for(let i=0;i<rows.length;i+=10){
  const part=rows.slice(i,i+10);
  out.push({ json:{ body:{ records:part.map(r=>{ const f={}; for(const k of Object.keys(r)){ if(k!=='id'&&k.charAt(0)!=='_') f[k]=r[k]; } return { id:String(r.id), fields:f }; }), typecast:true }, ids:part.map(r=>String(r.id)), size:part.length } });
}
return out;

// Write Check: the writer's count-back. Written rows are counted from every 2xx answer's records[];
// a request that was not 2xx counts every row it carried as a write error and names the ids. The
// writer never retries (a 429 locks the base for 30 s). Exactly one item out.
const n=(v)=>Number(v)||0;
const parse=(b)=>{ if(typeof b!=='string') return b; try{ return JSON.parse(b); }catch(e){ return null; } };
let chunks=[], resps=[];
try{ chunks=$('Chunk Rows').all().map(i=>i.json); }catch(e){}
try{ resps=$('Write Rows').all(); }catch(e){}
let written=0, writeErrors=0; const failed=[], reasons=[];
const note=(ids,why)=>{ for(const id of (ids||[])){ if(failed.length<200) failed.push(id); } const w=String(why||'').replace(/<[^>]+>/g,' ').replace(/\s+/g,' ').trim().slice(0,180); if(w&&reasons.length<10) reasons.push(w); };
resps.forEach((it,i)=>{
  const c=chunks[i]||{ size:0, ids:[] }; const j=it.json||{};
  if(j.error&&j.statusCode===undefined){ writeErrors+=n(c.size); note(c.ids,'row writer: '+String((j.error&&j.error.message)||j.error||'call failed')); return; }
  const status=n(j.statusCode); const b=parse(j.body===undefined?null:j.body);
  if(status>=200&&status<300&&b&&Array.isArray(b.records)){ written+=b.records.length; if(b.records.length<n(c.size)){ const back={}; for(const r of b.records) back[String((r||{}).id||'')]=1; writeErrors+=n(c.size)-b.records.length; note((c.ids||[]).filter(id=>!back[id]),(n(c.size)-b.records.length)+' of '+c.size+' records missing from a 2xx answer'); } return; }
  const e=b&&b.error; const why=e?(typeof e==='object'?(e.message||e.type||JSON.stringify(e)):String(e)):((j.error&&j.error.message)||(typeof j.body==='string'?j.body:''));
  writeErrors+=n(c.size); note(c.ids,'HTTP '+status+' '+String(why||'')+(status===429?' (rate limited; never retried)':''));
});
return [{ json:{ written, writeErrors, writeRequests:resps.length, failed, writeReasons:reasons } }];

// Build Batch Log: this batch's slice added to the run's own Hub row. The row is the accumulator
// (static data does not survive a sub-execution): Read Log Row fetched it, the totals are added,
// and the row is written back as Running; the parent writes the verdict after the last batch.
const r=$('Read Records').first().json;
const eid=String(r._execId);
const BLANK={ rows:0, done:0, verifying:0, noEmail:0, errored:0, byProvider:{}, mvCalls:0, blitzCalls:0, blitzFound:0, lmCalls:0, lmFound:0, guesses:0, catchAllDomains:0, written:0, writeErrors:0, writeWhy:[], batches:0, skips:[] };
let a=Object.assign({},BLANK);
try{ const prior=$('Read Log Row').first().json; const raw=prior&&prior.fields?prior.fields.Tally:null; if(raw){ const p=JSON.parse(String(raw)); if(p&&String(p.execId)===eid) a=Object.assign({},BLANK,p); } }catch(e){}
let s={}; try{ const v=$('Verdict').first().json||{}; s=v._stats||{}; }catch(e){}
const n=(v)=>Number(v)||0;
for(const k of ['rows','done','verifying','noEmail','errored','mvCalls','blitzCalls','blitzFound','lmCalls','lmFound','guesses','catchAllDomains']) a[k]+=n(s[k]);
for(const [k,v] of Object.entries(s.byProvider||{})) a.byProvider[k]=(a.byProvider[k]||0)+n(v);
if(s.blitzSkipped&&a.skips.indexOf('Blitz: '+s.blitzSkipped)<0) a.skips.push('Blitz: '+s.blitzSkipped);
if(s.lmSkipped&&a.skips.indexOf('LeadMagic: '+s.lmSkipped)<0) a.skips.push('LeadMagic: '+s.lmSkipped);
try{ const wc=$('Write Check').first().json||{}; a.written+=n(wc.written); a.writeErrors+=n(wc.writeErrors); for(const w of (wc.writeReasons||[])){ if(a.writeWhy.length<10&&a.writeWhy.indexOf(String(w))<0) a.writeWhy.push(String(w)); } }catch(e){}
a.batches+=1; a.execId=eid;
const total=n(r._total);
const prov=Object.entries(a.byProvider).map(([k,v])=>k+' '+v).join(', ')||'none';
const lines=[
  '**Running: '+a.rows+' of '+total+' people worked in '+a.batches+' batch'+(a.batches===1?'':'es')+', '+a.done+' resolved, '+a.verifying+' waiting on BounceBan, '+a.noEmail+' no email found, '+a.errored+' errored**',
  '', '**Table:** '+(r._tableName||'People')+' ('+(r._tableId||'')+') · view '+(r._view||''),
  '', '- **Resolved by provider:** '+prov,
  '- **MillionVerifier calls:** '+a.mvCalls+'; **guesses:** '+a.guesses+'; **Blitz:** '+a.blitzCalls+' asked, '+a.blitzFound+' found; **LeadMagic:** '+a.lmCalls+' asked, '+a.lmFound+' found; **catch-all domains:** '+a.catchAllDomains,
  '- **Rows written:** '+a.written+(a.writeErrors?', '+a.writeErrors+' refused':'')
];
if(a.skips.length) lines.push('', '**Skipped ('+a.skips.join('; ')+')**');
const row={ 'Execution ID':eid, 'Automation':'Enrich Emails', 'Status':'Running', 'Trigger':r._trigger||'form', 'Run at':r._startedAt, 'Target':(r._tableName||'People')+' ('+(r._tableId||'')+')', 'View':r._view||'', 'Records In':total, 'Records Out':a.written, 'Errors':a.errored+a.writeErrors, 'Tally':JSON.stringify(a), 'Description':lines.join('\n'), 'Execution Link':'https://n8n.flowroots.com/workflow/'+$workflow.id+'/executions/'+eid };
if(r._clientId) row['Client']=[r._clientId];
return [{ json:row }];

// Batch Response: the last node of the sub-execution; its output is what the parent receives.
// Counters only, never rows.
let s={}; try{ s=$('Verdict').first().json._stats||{}; }catch(e){}
let w={}; try{ w=$('Write Check').first().json||{}; }catch(e){}
return [{ json:{ done:s.done||0, verifying:s.verifying||0, noEmail:s.noEmail||0, errored:s.errored||0, written:w.written||0, writeErrors:w.writeErrors||0 } }];
